digo":"S22M-C05","legacy_id":489,"legacy_ids":[489],"relacionadas":[],"residual":"","coberturas":[{"legacy_id":489,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"En ONB_002 BLOQUEAR publicar Entidad regulada sin evidencia canónica regulatoria verificable o claims absolutos de seguridad sin evidencia técnica vigente, incluidos Tu información está segura, Datos encriptados y Registro seguro cuando se presenten como garantías no acreditadas. Captura Drive 1K7PdA_jOWMzwKTUkP7PGDQIWsNx6hbjI y decisión DEC-CLIENT-ONB002-VISUAL-COPY-NORMALIZATION-001 son evidencia visual, no prueba regulatoria. No afirmar regulación ni seguridad implementada. Binding pendiente."}],"hechos":["s22m05_render_claim_onb002","s22m05_regulacion_sin_evidencia","s22m05_seguridad_sin_evidencia","s22m05_captura_como_prueba_regulatoria"],"paquete":{"tipo":"NUEVA","codigo":"S22M-C05","clave":"s22m_legacy_489","familia":"UI_MESSAGES","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_ONBOARDING","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Claims regulatorios y de seguridad con evidencia","descripcion":"En ONB_002 BLOQUEAR publicar Entidad regulada sin evidencia canónica regulatoria verificable o claims absolutos de seguridad sin evidencia técnica vigente, incluidos Tu información está segura, Datos encriptados y Registro seguro cuando se presenten como garantías no acreditadas. Captura Drive 1K7PdA_jOWMzwKTUkP7PGDQIWsNx6hbjI y decisión DEC-CLIENT-ONB002-VISUAL-COPY-NORMALIZATION-001 son evidencia visual, no prueba regulatoria. No afirmar regulación ni seguridad implementada. Binding pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/489","solicitante":"Cristhian / Claude S22-M 2026-11-25"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22m05_render_claim_onb002"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22m05_regulacion_sin_evidencia"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22m05_seguridad_sin_evidencia"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22m05_captura_como_prueba_regulatoria"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22m05_render_claim_onb002":true,"s22m05_regulacion_sin_evidencia":false,"s22m05_seguridad_sin_evidencia":false,"s22m05_captura_como_prueba_regulatoria":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22m05_render_claim_onb002":true,"s22m05_regulacion_sin_evidencia":true,"s22m05_seguridad_sin_evidencia":false,"s22m05_captura_como_prueba_regulatoria":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22m05_render_claim_onb002":true,"s22m05_regulacion_sin_evidencia":false,"s22m05_seguridad_sin_evidencia":true,"s22m05_captura_como_prueba_regulatoria":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22m05_render_claim_onb002":true,"s22m05_regulacion_sin_evidencia":false,"s22m05_seguridad_sin_evidencia":false,"s22m05_captura_como_prueba_regulatoria":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22m05_render_claim_onb002":false,"s22m05_regulacion_sin_evidencia":true,"s22m05_seguridad_sin_evidencia":true,"s22m05_captura_como_prueba_regulatoria":true},"esperado":false}]},"hash":"b95627a32168a8a190af2ac9e06e3c9dbe6c6d67c320c2e27c1a7503c5d7538f","hash_paquete":"48f46e655a162e061b23aba8d472dd10e348e985a3d0c751df09b9f0d4956f05","hash_evaluado":"b95627a321","hash_paquete_10":"48f46e655a","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto','PASS','puntajes',p->'puntajes','juez','Claude','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','PR #4769 / Claude 2026-11-25 15:48 Lima / '||cd||' / hash_paquete_10='||(p->>'hash_paquete_10'));
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S22M_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision' IS DISTINCT FROM 'AUTO' THEN RAISE EXCEPTION 'S22M_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado' IS DISTINCT FROM 'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22M_PROMOTION_FAIL % %',cd,ans; END IF;
 n:=n+1;
 END LOOP;
 IF n<>5 OR vectors<>30 THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 cd:=p->>'codigo'; h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' THEN RAISE EXCEPTION 'S22M_COVERAGE_HASH_DRIFT %',cd; END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(p->'coberturas') LOOP
 lid:=(c->>'legacy_id')::int; residual:=c->>'residual'; diff:=c->>'diferencias';
 IF length(diff)<30 OR c->>'estado_cobertura' NOT IN ('REEMPLAZADA','PARCIAL') OR (c->>'estado_cobertura'='REEMPLAZADA' AND residual IS DISTINCT FROM '') OR (c->>'estado_cobertura'='PARCIAL' AND coalesce(length(residual),0)<15) THEN RAISE EXCEPTION 'S22M_COVERAGE_CONTRACT %',lid; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,1,c->>'estado_cobertura',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||(p->'paquete'->>'descripcion')||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-25 15:48 Lima'),h,'GPT / Claude S22-M independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22M_SOURCE_MISSING %',lid; END IF;
 END LOOP;
 END LOOP;
 cd:='S16-C02'; lid:=483;
 direct_hash:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF direct_hash IS NULL OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22M_DIRECT_ATTESTATION_MISSING %',cd; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 SELECT descripcion INTO new_desc FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1;
 diff:='S16-C02 conserva placeholder aprobado, error_text y anclajes invariantes de CTA y confianza.'; residual:='Falta acreditar contrato canónico de nueve dígitos iniciados en nueve, mensaje literal y reserva de línea en NORMAL.';
 IF length(diff)<30 OR ('PARCIAL'='PARCIAL' AND coalesce(length(residual),0)<15) OR ('PARCIAL'='REEMPLAZADA' AND residual IS DISTINCT FROM '') THEN RAISE EXCEPTION 'S22M_DIRECT_CONTRACT %',lid; END IF;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,1,'PARCIAL',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||new_desc||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-25 15:48 Lima'),direct_hash,'GPT / Claude S22-M independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22M_SOURCE_MISSING %',lid; END IF;
 cd:='S14-C11'; lid:=490;
 direct_hash:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF direct_hash IS NULL OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22M_DIRECT_ATTESTATION_MISSING %',cd; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 SELECT descripcion INTO new_desc FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1;
 diff:='S14-C11 conserva CAMPO_NRO_DOC y DNI por defecto, pero exige selector y permite CE y PASAPORTE bajo contrato vigente; no reinstala DNI_ONLY.'; residual:='La prohibición histórica de selector y otros documentos contradice la regla publicada; falta decisión explícita sobre intención legada y referencia de longitud DNI.';
 IF length(diff)<30 OR ('PARCIAL'='PARCIAL' AND coalesce(length(residual),0)<15) OR ('PARCIAL'='REEMPLAZADA' AND residual IS DISTINCT FROM '') THEN RAISE EXCEPTION 'S22M_DIRECT_CONTRACT %',lid; END IF;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,1,'PARCIAL',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||new_desc||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-25 15:48 Lima'),direct_hash,'GPT / Claude S22-M independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22M_SOURCE_MISSING %',lid; END IF;
 cd:='M4-B05'; lid:=494;
 direct_hash:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF direct_hash IS NULL OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S22M_DIRECT_ATTESTATION_MISSING %',cd; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 SELECT descripcion INTO new_desc FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1;
 diff:='M4-B05 gobierna habilitación visual de reenvío OTP a partir de timer AUTH/OTP_ORDINARY_RESEND_TIMER_SECONDS y tiempo server-side.'; residual:='Falta acreditar política OTP_POL_B2B_AUTH_EMAIL_BREVO y desafío PASSWORD_RECOVERY, expiración del código y anti-enumeración en B2B-AUTH-006.';
 IF length(diff)<30 OR ('PARCIAL'='PARCIAL' AND coalesce(length(residual),0)<15) OR ('PARCIAL'='REEMPLAZADA' AND residual IS DISTINCT FROM '') THEN RAISE EXCEPTION 'S22M_DIRECT_CONTRACT %',lid; END IF;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,1,'PARCIAL',diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||new_desc||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente 2026-11-25 15:48 Lima'),direct_hash,'GPT / Claude S22-M independiente')
 ON CONFLICT (legacy_id,nucleo_codigo,version_nucleo) DO UPDATE SET estado_cobertura=EXCLUDED.estado_cobertura, diferencias=EXCLUDED.diferencias, evidencia=EXCLUDED.evidencia, hash_paquete=EXCLUDED.hash_paquete, revisado_por=EXCLUDED.revisado_por;
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S22M_SOURCE_MISSING %',lid; END IF;
 SELECT count(DISTINCT legacy_id) INTO after_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND (links<>8 OR after_replaced<>before_replaced+3) THEN RAISE EXCEPTION 'S22M_COVERAGE_READBACK_FAIL links=% before=% after=%',links,before_replaced,after_replaced; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22M_POST_COVERAGE_INVARIANT_FAIL'; END IF;
 RAISE NOTICE 'S22M_PASS 5 JUICIOS 5 AUTO 30 VECTORES links=% replaced=% DPIG03=0',links,after_replaced;
END $s22$;
COMMIT;
